import csv
import sqlite3

def load_credentials(csv_file):
    """Load user credentials from CSV file into memory."""
    credentials = {}
    with open(csv_file, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            credentials[row['username']] = {
                'password': row['password'],
                'user_id': row['user_id']
            }
    return credentials

def validate_login(username, password, credentials):
    """Check if provided credentials match stored values."""
    if username not in credentials:
        return False, None

    stored_password = credentials[username]['password']
    if password == stored_password:
        return True, credentials[username]['user_id']
    return False, None

def main():
    creds = load_credentials('users.csv')

    username = input('Username: ')
    password = input('Password: ')

    success, user_id = validate_login(username, password, creds)
    if success:
        print(f'Login successful. User ID: {user_id}')
    else:
        print('Login failed.')

if __name__ == '__main__':
    main()
